{"contents": "#!/usr/bin/env python3
import base64, math, collections
from rfc8032 import point_mul, G, point_compress

ctxt = open('ciphertext','rb').read()
parts = ctxt.split(b';')
KEYLEN = 12
tbl = {}
for j in range(0, 601):
    tbl[base64.b64encode(point_compress(point_mul(j, G)))] = j
S = [tbl.get(p) for p in parts]

key = [None]*KEYLEN
for i,ch in enumerate('flag{'):
    key[i] = S[i] - ord(ch)

allowed = set(range(32,127)) | {9,10,13}
cands = {}
for j in range(KEYLEN):
    if key[j] is not None:
        cands[j] = [key[j]]
    else:
        cands[j] = [k for k in range(256)
                if all((S[i]-k) in allowed for i in range(j, len(S), KEYLEN) if S[i] is not None)]

# unigram english-ish log freq
freq = {' ':18.0,'e':10.2,'t':7.5,'a':6.5,'o':6.3,'i':5.7,'n':5.7,'s':5.1,'r':5.0,'h':4.9,
        'l':3.3,'d':3.3,'c':2.3,'u':2.3,'m':2.0,'f':1.8,'p':1.6,'g':1.9,'w':1.7,'y':1.7,
        'b':1.2,'v':0.8,'k':0.6,'x':0.12,'j':0.1,'q':0.05,'z':0.05,'.':1.0,',':0.9,"'":0.8,
        '{':0.02,'}':0.02,'\n':0.3}
def score(chars):
    s = 0.0
    for ch in chars:
        c = ch.lower()
        s += math.log(freq.get(c, 0.02)/100 + 1e-9)
        if not (ch.isalnum() or ch in " .,'-\n{}()_!:;?"):
            s -= 3
    return s

for j in range(KEYLEN):
    if len(cands[j]) == 1:
        continue
    scored = []
    for k in cands[j]:
        chars = [chr(S[i]-k) for i in range(j, len(S), KEYLEN) if S[i] is not None]
        scored.append((score(chars)/len(chars), k, ''.join(chars)))
    scored.sort(reverse=True)
    print("=== pos", j)
    for sc,k,ch in scored:
        print("   k=%3d  score=%8.3f  %s" % (k, sc, ch))
